SELECT CASE WHEN regexp_matches(json_extract_string(p.value,'$'),'#[0-9]+(-[0-9]+)?$') THEN 'numeric_range' WHEN contains(json_extract_string(p.value,'$'),'#') THEN 'symbol' ELSE 'plain' END shape,count(*) paths FROM calls,json_each(json_extract(input,'$.paths')) p WHERE tool_name LIKE '%tilth_read' GROUP BY shape;
SELECT arm,tool_name,coalesce(json_extract_string(input,'$.mode'),json_extract_string(input,'$.output_mode'),'omitted') read_mode,count(*) calls FROM calls WHERE tool_name LIKE '%tilth_read' OR tool_name LIKE '%__Search' GROUP BY arm,tool_name,read_mode ORDER BY arm,read_mode;
SELECT arm,tool_name, count(*) requests,count(DISTINCT (sessionId,p.value)) unique_exact_requests FROM calls,json_each(coalesce(json_extract(input,'$.paths'),json_extract(input,'$.file_glob_patterns'))) p WHERE tool_name LIKE '%tilth_read' OR tool_name LIKE '%__Search' GROUP BY arm,tool_name;
